import json

with open('inventory.json') as f:
    inv = json.load(f)

rejected = []
with open('transactions.txt') as f:
    lines = f.read().splitlines()

for i, line in enumerate(lines, 1):
    s = line.strip()
    if not s:
        continue
    parts = s.split()
    if len(parts) != 3:
        continue
    op, sku, qty = parts
    try:
        q = int(qty)
    except ValueError:
        continue
    if op == 'add':
        inv[sku] = inv.get(sku, 0) + q
    elif op == 'remove':
        cur = inv.get(sku)
        if cur is None or cur - q < 0:
            rejected.append(i)
        else:
            inv[sku] = cur - q

with open('inventory_after.json', 'w') as f:
    json.dump(inv, f, indent=2)
    print('', file=f)

with open('rejected.txt', 'w') as f:
    for n in rejected:
        print(n, file=f)
